// 统计字符串中字符出现的频率
function countCharacters(text) {
    const charCount = {};

    for (const char of text) {
        if (/[a-zA-Z0-9]/.test(char)) {
            const lowerChar = char.toLowerCase();
            charCount[lowerChar] = (charCount[lowerChar] || 0) + 1;
        }
    }

    return charCount;
}

// 测试字符统计
const text = "Hello World! How are you?";
const frequency = countCharacters(text);

console.log(`原文本: ${text}`);
console.log("
字符出现频率:");
for (const [char, count] of Object.entries(frequency).sort()) {
    console.log(`'${char}': ${count}`);
}

// 找出出现最多的字符
const mostCommon = Object.entries(frequency).reduce((a, b) => a[1] > b[1] ? a : b);
console.log(`
出现最多的字符: '${mostCommon[0]}' (${mostCommon[1]}次)`);
